import pytest
from dimensions import calculate_aspect_ratio

def test_invalid_dimension():
    # Passes before fix
    with pytest.raises(ValueError):
        calculate_aspect_ratio(0, 100)

def test_integer_ratio():
    # Passes before fix (4 // 2 == 2.0)
    assert calculate_aspect_ratio(400, 200) == 2.0

def test_sixteen_nine():
    assert calculate_aspect_ratio(1920, 1080) == 1.78

def test_fractional_less_than_one():
    assert calculate_aspect_ratio(1080, 1920) == 0.56

reference_fix.dimensions.py:
def calculate_aspect_ratio(width: int, height: int) -> float:
    """Return aspect ratio (width / height) rounded to 2 decimal places."""
    if height <= 0 or width <= 0:
        raise ValueError('Dimensions must be positive')
    return round(width / height, 2)
